// Wandering merchant: first after 10 minutes of play, then every 12-18 minutes, a camel trader waits on the map for 25 s; a tap pays about 45 s of income.
let merchantAt=Date.now()+10*60000,merchant=null;
function merchantTick(){const now=Date.now(),s=c.state();if(merchant){if(now>merchant._until||!c.onMap())leaveMerchant();return;}if(now<merchantAt||!started||!s.journey.introDone||!c.onMap()||c.readonly()||document.hidden||document.querySelector('dialog[open]'))return;
 const m=document.createElement('button');m.id='merchant';m.setAttribute('aria-label',t('merchant.aria'));m.innerHTML='<img src="'+ART+'camel.webp" alt=""><span class="m-bubble"><img src="'+ART+'gold.webp" alt=""></span>';m.style.left=rand(22,62)+'%';m.style.top=rand(27,37)+'%';m._until=now+25000;
 m.onclick=()=>{const from=m.getBoundingClientRect();if(ads.available&&!c.readonly()&&E.can(c.state(),'merchant')){leaveMerchant();offer('merchant');return;}if(E.act(c.state(),'merchant')){services.track('merchant_tap');c.save();tone('reward');flyCoins(from,10);buzz(25);}leaveMerchant();};merchant=m;phone.append(m);}
function leaveMerchant(){const m=merchant;merchant=null;merchantAt=Date.now()+rand(12,18)*60000;if(!m)return;m.classList.add('leave');setTimeout(()=>m.remove(),500);}
// Mission medallion: a progress ring around the quest book; tap to slide out the title. It opens by itself when the reward is ready.
// Early phase (the first pass of the Valley, until its first re-founding): bigger book, the mission always written out with one line on why,
// and a red badge while a mission is new (not yet looked at) or ready to claim.
let stripOpen=false,stripTimer=0,seenMission=null;const WHY=['hireWorker','hireDriver','hireMarket','buildingLevel','caravanLevel','openTown','sell','prestigeTarget'];
// What must exist before a mission can be done: the hut before its worker or level, the caravan before its driver or
// level, and one trip sent by hand before a driver can be hired.
function needFirst(s,m){const l=m.town&&s.lines[m.town];if(!l||!l.open)return null;if(['hireWorker','buildingLevel'].includes(m.type)&&!l.buildings[0].open)return 'build';if(['hireDriver','caravanLevel'].includes(m.type)&&!l.caravan)return 'caravan';if(m.type==='hireDriver'&&!E.handsFree(m.town)&&!(l.trips>0&&l.manualDispatches>0))return 'dispatch';return null;}
function seeMission(){const s=c.state(),m=s.journey?.introDone&&J.mission(s,E,c.region());if(m)seenMission=m.id;}
function medal(icon,label,badge){return '<button id="missionMedal" aria-label="'+esc(label)+'">'+(badge?'<span class="mbadge" aria-hidden="true">!</span>':'')+'<svg viewBox="0 0 58 58" aria-hidden="true"><circle cx="29" cy="29" r="25" fill="none" stroke="#0007" stroke-width="6"/><circle class="ring" cx="29" cy="29" r="25" fill="none" stroke="#f2cd6b" stroke-width="6" stroke-linecap="round" stroke-dasharray="'+RING+'" stroke-dashoffset="'+RING+'"/></svg><img src="'+ART+icon+'.webp" alt=""></button>';}
function toggleStrip(){seeMission();stripOpen=!stripOpen;clearTimeout(stripTimer);if(stripOpen)stripTimer=setTimeout(()=>{stripOpen=false;updateGoal();},6000);updateGoal();}
// Second town (first real milestone after the tutorial): one celebration and a one-time gift of about 5 minutes of income.
function secondTownCheck(s){const j=s.journey,id=E.orders.forest[1];if(!started||c.readonly()||!j?.introDone||j.secondTown===1||!s.lines[id]?.open)return;const gift=J.secondTownGift(s,E);if(!gift)return;c.save();services.track('second_town',{gift_log10:Math.round(Math.log10(Math.max(1,gift)))});celebrate(['cele.secondTown',{town:N(E.defs[id].name)}],['cele.rewardText',{n:fmt(gift)}],'goal');}
function updateGoal(){hint();const s=c.state(),strip=$('goalStrip');secondTownCheck(s);if(!s.journey.introDone){strip.hidden=true;return;}strip.hidden=false;const r=c.region(),m=J.mission(s,E,r),list=m?.ready?J.readyMissions(s,E,r):[],early=!((s.regions.forest.prestige||0)>0||s.extras.empire.resets>0),fresh=!!m&&(m.ready||seenMission!==m.id);let html,p=1;
 if(!m){const text=J.level(s)>=J.PRESTIGE_LEVEL?t('missions.prestigeReady',{region:N(R[r].name),n:E.multiplier(s,r)+1}):t('missions.prestigeLocked',{n:J.PRESTIGE_LEVEL});html=medal('prestige',text)+'<div class="mpill"><button id="openGoals">'+esc(text)+'</button></div>';}
 // The ring updates in place so taps are never lost to a rebuild.
 else{p=Math.min(1,m.value/m.target);const many=list.length>1,total=list.reduce((n,x)=>n+x.reward,0),best=list.length?Math.max(...list.map(x=>x.reward)):0,title=many?t('missions.ready',{n:list.length}):missionTitle(m),label=title+' '+fmt(Math.min(m.value,m.target))+'/'+fmt(m.target),need=!m.ready&&needFirst(s,m),why=!m.ready&&(need||early&&WHY.includes(m.type))?'<span class="mwhy">'+esc(t(need?'why.first.'+need:'why.'+m.type))+'</span>':'';html=medal('quests',label,fresh)+'<div class="mpill"><button id="openGoals" aria-label="'+esc(label)+'"><span class="mtitle">'+(m.ready?'✓ ':'')+esc(title)+'</span>'+why+'</button>'+(m.ready?'<button id="claimGoal" aria-label="'+t('goals.claimAria')+' +'+fmt(total)+'">+'+fmt(total)+'<img class="ico" src="'+ART+'gold.webp" alt=""></button>'+(ads.available?'<button id="claimGoalAd" class="ad-btn" aria-label="'+esc(many?t('quest.adAria',{n:fmt(best)}):t('goals.claimAria')+' x2')+'">'+adLabel(2)+'</button>':''):'')+'</div>';}
 if(strip.dataset.html!==html){strip.dataset.html=html;strip.innerHTML=html;$('openGoals').onclick=openGoals;$('missionMedal').onclick=toggleStrip;if($('claimGoal'))$('claimGoal').onclick=claim;if($('claimGoalAd'))$('claimGoalAd').onclick=claimDouble;}
 const ready=!!m?.ready;strip.querySelector('.ring').style.strokeDashoffset=RING*(1-p);strip.classList.toggle('ready',ready);strip.classList.toggle('early',early);strip.classList.toggle('open',ready||stripOpen||early);$('missionMedal').setAttribute('aria-expanded',String(ready||stripOpen||early));
 // Only the first ready quest gets the card; while one is waiting, the bar just counts up.
 if(started&&list.length){const shown=s.journey.missionShown,fresh=list.filter(x=>!shown.includes(x.id));if(fresh.length){shown.push(...fresh.map(x=>x.id));s.journey.missionShown=shown.slice(-40);c.save();if(fresh.length===list.length)celebrate(['cele.mission'],['cele.rewardText',{n:fmt(list.reduce((n,x)=>n+x.reward,0))}],'goal');}}
}
// Road goal card: the one big next step of the journey, its progress, what still blocks it and what it opens.
function roadWords(q){return t(q.key,{region:q.region?N(R[q.region].name):'',town:q.town?N(E.defs[q.town].name):'',n:q.n??''});}
function roadTitle(g){return g.type==='openRegion'?t('road.open',{region:N(R[g.region].name)}):t('road.refound',{region:N(R[g.region].name)});}
function roadHtml(s,compact){const g=J.roadGoal(s,E),p=g.target?Math.min(1,g.value/g.target):1;
 let h='<div class="road-goal'+(g.ready?' ready':'')+'"><p class="road-head">'+esc(t('road.label'))+'</p><p class="road-title"><b>'+esc(roadTitle(g))+'</b></p><div class="road-bar"><i style="width:'+(p*100).toFixed(1)+'%"></i></div><p class="road-num">'+fmt(g.value)+' / '+fmt(g.target)+'<img class="ico" src="'+ART+'gold.webp" alt=""></p>';
 if(!compact&&g.blocks.length)h+='<p class="road-blocks">'+esc(t('road.needs'))+' '+g.blocks.map(q=>esc(roadWords(q))).join(' · ')+'</p>';
 return h+'<p class="road-gains">→ '+g.gains.map(q=>esc(roadWords(q))).join(' · ')+'</p></div>';}
function openGoals(){seeMission();const s=c.state(),r=c.region(),m=J.mission(s,E,r);$('goalsTitle').textContent=t('missions.title',{region:N(R[r].name)});let html=roadHtml(s)+'<p>'+t('goals.level',{level:J.level(s),earned:fmt(s.earned),next:fmt(J.next(s))})+'</p>';
 if(m)html+='<p class="mission-step">'+t('missions.step',{i:m.index+1,count:m.count})+'</p><p><b>'+missionTitle(m)+'</b></p><p>'+fmt(Math.min(m.value,m.target))+' / '+fmt(m.target)+'</p><p>'+t('cele.rewardText',{n:fmt(m.reward)})+'</p><button id="showMission">'+t('missions.show')+'</button>'+
  (J.upcoming(s,E,r).length?'<p class="mission-next">'+t('missions.next')+': '+J.upcoming(s,E,r).map(x=>missionTitle({...x,target:0})).join(' · ')+'</p>':'');
 else html+='<p><b>'+t('prestige.title')+'</b></p><p>'+t('prestige.next',{now:E.multiplier(s,r),next:E.multiplier(s,r)+1})+'</p><button id="showMission">'+t('missions.show')+'</button>';
 if(bookWaiting(s))html+='<button id="goBook">'+esc(t('book.tipGo'))+'</button>';
 html+='<small>'+t('goals.spendNote')+'</small>';const pages=(s.journey.story?.seen||[]).map(k=>STORY.find(x=>x.key===k)).filter(Boolean);if(pages.length)html+='<details class="ledger"><summary>'+esc(t('ledger.title'))+' ('+pages.length+')</summary><div class="ledger-list">'+[...pages].reverse().map(x=>'<p><b>'+esc(t('talk.'+x.who))+'</b>'+esc(storyText(x))+'</p>').join('')+'</div></details>';$('goalDetail').innerHTML=html;$('showMission').onclick=()=>{$('goalsDialog').close();c.focus(m||{type:'prestige',home:r,region:r});};if($('goBook'))$('goBook').onclick=()=>{$('goalsDialog').close();c.showTown('book');};if(!$('goalsDialog').open)$('goalsDialog').showModal();}
$('playerBadge').onclick=openGoals;$('closeGoals').onclick=()=>$('goalsDialog').close();
$('musicToggle').onclick=()=>{const j=c.state().journey;j.music=j.music===false;services.track('setting_change',{name:'music',on:String(j.music)});c.save();music.update();update();};$('animToggle').onclick=()=>{const j=c.state().journey;j.animations=j.animations===false;services.track('setting_change',{name:'animations',on:String(j.animations)});c.save();update();};$('vibrationToggle').onclick=()=>{const j=c.state().journey;j.vibration=j.vibration===false;c.save();if(j.vibration)buzz(30);update();};
$('feedbackBtn').onclick=feedback;
$('awakeToggle').onclick=()=>{const j=c.state().journey;j.keepAwake=j.keepAwake===false;c.save();keepAwake();update();};
$('soundToggle').onclick=()=>{unlockAudio();c.state().journey.sound=!c.state().journey.sound;services.track('setting_change',{name:'sound',on:String(c.state().journey.sound)});c.save();update();};
const switchLanguage=()=>I.set(I.lang==='tr'?'en':'tr');$('languageToggle').onclick=switchLanguage;$('welcomeLanguage').onclick=switchLanguage;
$('welcomeNew').hidden=!c.existing();$('welcomeNew').onclick=()=>$('resetDialog').showModal();
// Welcome-back card: the gold is already credited; Collect is the moment of reward (and the slot for a later x2 offer).
function duration(seconds){const m=Math.max(1,Math.round(seconds/60)),h=Math.floor(m/60);return h?t('time.hm',{h,m:m%60}):t('time.m',{m});}
// Coin-bag card: time away with a clock icon, the amount counts up, Collect flies the coins into the gold pill.
// Welcome-back spotlight: the town that sold the most while away, and the best upgrade the player can now afford.
function spotlight(sold){const s=c.state(),box=$('awaySpot');let html='';const top=Object.entries(sold||{}).filter(([id,n])=>n>0&&E.defs[id]).sort((a,b)=>b[1]-a[1])[0];
 if(top){const d=E.defs[top[0]];html+='<p class="spot-line"><img src="'+ART+'market.webp" alt=""><span>'+t('away.spotTown',{town:esc(N(d.name)),n:fmt(top[1]),product:esc(N(d.product))})+'</span></p>';}
 let best=null;for(const id of E.IDS){const l=s.lines[id];if(!l?.buildings)continue;l.buildings.forEach((b,i)=>{if(!b.open)return;const m=E.toMilestone(s,id,i);if(m.affordable&&m.n>0&&(!best||m.cost>best.cost))best={id,cost:m.cost};});}
 if(best){html+='<button class="spot-go" data-town="'+best.id+'"><img src="'+ART+'up.webp" alt=""><span>'+t('away.spotBuy',{town:esc(N(E.defs[best.id].name))})+'</span></button>';}
 if(s.journey?.introDone)html+=roadHtml(s,true);
 box.innerHTML=html;box.hidden=!html;const go=box.querySelector('.spot-go');if(go)go.onclick=()=>{const id=go.dataset.town;$('awayCollect').click();setTimeout(()=>c.focus({type:'buildingLevel',town:id,home:E.defs[id].region}),350);};}
// Back after a real absence with nothing earned: say which step is missing for the towns to work alone, with a button to it.
const gapText=g=>t('idle.'+g.kind,{town:g.town?N(E.defs[g.town].name):''});
function gapFocus(g){c.focus({type:g.kind==='market'?'hireMarket':'hireWorker',town:g.town,home:g.region,region:g.region});}
function idleBack(){const g=E.idleGap(c.state());if(!g||c.readonly()||$('awayDialog').open)return;awayIdle=true;awayGain=0;$('awayTitle').textContent=t('idle.title');$('awayText').textContent=gapText(g);$('awayDialog').setAttribute('aria-label',t('idle.title'));$('awayDialog').querySelector('.away-gold').style.display='none';$('awayCap').hidden=true;$('awayCollect').textContent=t('talk.ok');$('awayDouble').hidden=true;
 const box=$('awaySpot');box.innerHTML='<button class="spot-go"><img src="'+ART+'up.webp" alt=""><span>'+esc(t('missions.show'))+'</span></button>';box.hidden=false;box.querySelector('.spot-go').onclick=()=>{awayIdle=false;$('awayDialog').close();setTimeout(()=>gapFocus(g),350);};services.track('welcome_back_idle',{kind:g.kind});$('awayDialog').showModal();}
function welcomeBack(seconds,gold,sold){if(!c.state().journey?.introDone)return;if(!(gold>0)){idleBack();return;}awayIdle=false;$('awayDialog').querySelector('.away-gold').style.display='';spotlight(sold);const limit=E.offlineLimit(c.state()),time=duration(Math.min(seconds,limit));$('awayTitle').textContent=t('away.title');$('awayText').innerHTML='<img class="ico" src="'+ART+'time.webp" alt="">'+esc(time);$('awayDialog').setAttribute('aria-label',t('away.text',{time,gold:fmt(gold)}));
 const capped=seconds>limit+60;$('awayCap').textContent=capped?t('away.capped',{h:limit/3600}):'';$('awayCap').hidden=!capped;$('awayCollect').textContent=t('away.collectShort');awayGain=gold;$('awayDouble').hidden=!ads.available;$('awayDouble').innerHTML=adLabel(2);services.track('welcome_back',{minutes:Math.round(Math.min(seconds,limit)/60),gold_log10:Math.round(Math.log10(Math.max(1,gold)))});if(!$('awayDialog').open)$('awayDialog').showModal();countUp($('awayGold'),gold);}
function countUp(node,value){if(!motion){node.textContent=fmt(value);return;}const t0=performance.now(),run=now=>{const p=Math.min(1,(now-t0)/1100);node.textContent=fmt(value*(1-Math.pow(1-p,3)));if(p<1&&$('awayDialog').open)requestAnimationFrame(run);else node.textContent=fmt(value);};node.textContent=fmt(0);requestAnimationFrame(run);}
$('awayCollect').onclick=()=>{const from=$('awayCollect').getBoundingClientRect();$('awayDialog').close();if(awayIdle){awayIdle=false;return;}tone('sale');flyCoins(from,10);};
// Rewarded ads (Android app; hidden elsewhere). Every reward is paid only after the SDK reports it as earned.
let adBusy=false,awayGain=0,awayIdle=false,adOffer=null;
const adLabel=n=>'<img class="ico" src="'+ART+'reward-video.webp" alt="">x'+n;
async function watch(placement,button){if(adBusy||c.readonly())return false;adBusy=true;if(button)button.disabled=true;const ok=await ads.show(placement);adBusy=false;if(button)button.disabled=false;
 if(!ok&&button){const old=button.innerHTML;button.textContent=t('ad.failed');setTimeout(()=>{button.innerHTML=old;},2500);}return ok;}
// Construction speed-up from the town panel: one ad = 30 min less.
window.KervanAdConstruct=async(id,i,button)=>{if(!ads.available)return;if(await watch('construct',button)&&E.adConstruct(c.state(),id,i)){c.changed('build',id,button.getBoundingClientRect());tone('reward');buzz([30,50,30]);}};
function payAd(kind,gold,from,coins=12){if(!E.adReward(c.state(),kind,gold))return;c.changed();tone('reward');flyCoins(from,coins);buzz([30,50,30]);updateAds();}
$('awayDouble').onclick=async()=>{const b=$('awayDouble');if(await watch('welcome_back',b)){const from=b.getBoundingClientRect();$('awayDialog').close();payAd('welcome_back',awayGain,from);}};
$('dailyDouble').onclick=async()=>{const b=$('dailyDouble'),s=c.state(),gold=E.dailyReward(s);if($('dailyDialog').classList.contains('claiming')||!E.can(s,'daily',today()))return;if(await watch('daily',b)&&E.act(s,'daily',today())){const from=b.getBoundingClientRect();$('dailyDialog').close();services.track('daily_claim',{day:s.extras.daily.next||7,ad:1});payAd('daily',gold,from);const v=E.critterVisit(s,today());if(v){c.changed();services.track('critter_visit',{id:v});setTimeout(()=>critterArrive(v),1200);}}};
// One dialog for the merchant offer, the x2 sales boost and the free chest.
function offer(kind){const s=c.state(),o={kind};adOffer=o;let icon='speed',title,text,watchLabel=t('ad.watch'),close=t('ad.close');
 if(kind==='merchant'){icon='camel';title=t('ad.merchantTitle');o.gold=E.merchantReward(s);text=t('ad.merchantText',{n:fmt(o.gold),m:fmt(o.gold*2)});watchLabel=null;close=t('away.collectShort');}
 else if(kind==='boost'){title=t('ad.boostTitle');text=t('ad.boostText')+(s.extras.adBoost>0?' '+t('ad.boostLeft',{time:clock(s.extras.adBoost)}):'');if(s.extras.adBoost+E.AD_BOOST>E.AD_BOOST_CAP)watchLabel=null,text+=' '+t('ad.boostFull');}
 else{icon='treasury';title=t('ad.chestTitle');text=t('ad.chestText',{n:fmt(E.chestReward(s))});}
 $('adIcon').src=ART+icon+'.webp';$('adTitle').textContent=title;$('adText').textContent=text;$('adClose').textContent=close;
 $('adWatch').hidden=!watchLabel&&kind!=='merchant';$('adWatch').innerHTML=kind==='merchant'?adLabel(2):'<img class="ico" src="'+ART+'reward-video.webp" alt="">'+esc(watchLabel||'');$('adDialog').showModal();}
$('adClose').onclick=()=>{const o=adOffer;$('adDialog').close();if(o?.kind==='merchant'&&E.act(c.state(),'merchant')){services.track('merchant_tap');c.save();tone('reward');flyCoins($('adClose').getBoundingClientRect(),10);buzz(25);}};
$('adDialog').addEventListener('cancel',e=>{if(adOffer?.kind==='merchant'){e.preventDefault();$('adClose').onclick();}});
$('adWatch').onclick=async()=>{const o=adOffer,b=$('adWatch');if(!o)return;const placement=o.kind==='merchant'?'merchant':o.kind==='boost'?'boost':'chest';if(!await watch(placement,b))return;const from=b.getBoundingClientRect();$('adDialog').close();
 if(o.kind==='merchant'){if(E.act(c.state(),'merchant'))services.track('merchant_tap',{ad:1});payAd('merchant',o.gold,from);}else payAd(o.kind,0,from);adOffer=null;};
// Leyla and the feature cards share one small dialog. Lines queue up, so two cards opening together show in turn.
const HELP={token:['token.title','token'],book:['book.title','trade'],rush:['rush.title','speed'],seals:['seal.title','seal'],inn:['inn.title','inn']};let talkLines=[];
function talkShow(){const x=talkLines[0];$('talkPic').src=x.pic;$('talkName').textContent=x.name;$('talkText').textContent=x.text;$('talkNext').textContent=t(talkLines.length>1?'talk.next':'talk.ok');$('talkSkip').hidden=talkLines.length<2;$('talkSkip').textContent=t('talk.skip');if(!$('talkDialog').open)$('talkDialog').showModal();}
function talk(lines){talkLines.push(...lines);talkShow();}
$('talkNext').onclick=()=>{talkLines.shift();if(talkLines.length)talkShow();else $('talkDialog').close();};$('talkSkip').onclick=()=>{talkLines=[];$('talkDialog').close();};$('talkDialog').addEventListener('close',()=>{talkLines=[];});
function help(key){talk([{pic:ART+HELP[key][1]+'.webp',name:t(HELP[key][0]),text:t('help.'+key)}]);}
function firstHelp(key){const j=c.state().journey;j.help=j.help||{};if(j.help[key]||!started||!j.introDone)return;j.help[key]=1;c.save();help(key);}
// Road Ledger (story.js): one short line at a time from real progress. It never blocks play, and what was said stays in the ledger.
// An older save has the moments it already passed written in silently, with one line to say so.
const STORY=window.GameStory,storyPic=who=>'../assets/art-v2/portraits/'+who+'.webp',storyText=x=>t('story.'+x.key,{town:x.town?N(x.town(E)):''});let storyTimer=0,storyGap=0,storyGo=null;
// Trade Book pointer: once, during the long "earn" goal, if the player has never taken a job. A tap on the line opens the Book.
const bookWaiting=s=>{const x=s.extras.book;if(x.jobs||x.job||!E.bookOpen(s))return false;const m=J.mission(s,E,c.region());return !!m&&!m.ready&&m.type==='prestigeTarget';};
function bookTip(s){const j=s.journey;if(!started||!j.introDone||j.bookTip||c.readonly()||document.hidden||!$('storyLine').hidden||Date.now()-storyGap<1500||document.querySelector('dialog[open]')||!bookWaiting(s))return;j.bookTip=1;c.save();storyShow('leyla',null,t('book.tip'));storyGo=()=>c.showTown('book');clearTimeout(storyTimer);storyTimer=setTimeout(storyHide,15000);}
function storyInit(s){const j=s.journey;if(j.story)return;j.story={seen:[]};if(!j.introDone)return;for(const x of STORY)if(x.when(s,E))j.story.seen.push(x.key);if(j.story.seen.length)storyShow('leyla','story.recap');}
function storyShow(who,key,text){storyGo=null;$('storyPic').src=storyPic(who);$('storyName').textContent=t('talk.'+who);$('storyText').textContent=text||t(key);$('storyLine').hidden=false;clearTimeout(storyTimer);storyTimer=setTimeout(storyHide,8000);}
function storyHide(){$('storyLine').hidden=true;storyGap=Date.now();}
$('storyLine').onclick=()=>{const go=storyGo;storyGo=null;storyHide();if(go)go();};
// The first tokens get the card; later ones a short note.
let tokensSeen=c.state().extras.tokens;function tokenTick(s){const n=s.extras.tokens,more=n-tokensSeen;tokensSeen=n;if(!started||!s.journey.introDone||n<1)return;if(!s.journey.help?.token){if(!celebrating&&!queue.length)firstHelp('token');else tokensSeen=n-more;return;}if(more>0)c.toast(t('token.earned',{n:more}));}
// During the tutorial Leyla only speaks while the player waits, so her line never sits beside a step to do.
function storyTick(s){if(!started||c.readonly()||document.hidden)return;if(!s.journey.introDone&&!['productionWait','travelWait','saleWait'].includes(stage))return;storyInit(s);if(!$('storyLine').hidden||Date.now()-storyGap<1500)return;const seen=s.journey.story.seen,next=STORY.find(x=>!seen.includes(x.key)&&x.when(s,E));if(!next)return;seen.push(next.key);c.save();storyShow(next.who,null,storyText(next));}
$('adBoostBtn').onclick=()=>offer('boost');$('chestBtn').onclick=()=>offer('chest');
$('privacyBtn').onclick=()=>ads.privacy().then(updateAds);
// In the app an outside address opens in the phone's browser; in a plain web page it must not replace the game.
// Update reminder (phones only): kervan-updates/latest.json names the newest store build per platform. When it is newer than this one,
// a card offers the store page, at most once a day. Nothing is downloaded or installed by the game itself.
const APP_BUILD=67,LATEST='https://ffgamelabs-gif.github.io/kervan-updates/latest.json',STORE={android:'https://play.google.com/store/apps/details?id=com.kervanyollari.game',ios:'https://apps.apple.com/app/id6829555841'};
function checkStore(){const platform=window.Capacitor?.getPlatform?.();if(!services.native||!STORE[platform])return;let last=0;try{last=+localStorage.getItem('kervan_update_asked')||0;}catch{}if(Date.now()-last<864e5)return;
 fetch(LATEST,{cache:'no-store'}).then(r=>r.ok?r.json():null).then(j=>{const newest=Math.floor(Number(j?.[platform]?.build)||0);if(newest<=APP_BUILD)return;try{localStorage.setItem('kervan_update_asked',String(Date.now()));}catch{}
  let d=$('updateDialog');if(!d){phone.insertAdjacentHTML('beforeend','<dialog id="updateDialog"><h2></h2><p></p><button id="updateGo"></button><button id="updateLater"></button></dialog>');d=$('updateDialog');}
  d.querySelector('h2').textContent=t('update.title');d.querySelector('p').textContent=t('update.text');$('updateGo').textContent=t('update.go');$('updateLater').textContent=t('update.later');
  $('updateLater').onclick=()=>d.close();$('updateGo').onclick=()=>{d.close();location.href=STORE[platform];};d.showModal();}).catch(()=>{});}
setTimeout(checkStore,8000);
$('policyBtn').onclick=()=>{const url='https://sites.google.com/view/ffgamelabs-privacy/ana-sayfa';if(services.native)location.href=url;else window.open(url,'_blank');};
const clock=sec=>{const m=Math.ceil(sec/60);return m>=60?t('time.hm',{h:Math.floor(m/60),m:m%60}):t('time.m',{m});};
// The boost and chest buttons wait for five minutes of play, so a new player's first minutes are about the game, not ads.
const AD_HUD_AFTER=300;
function updateAds(){const s=c.state(),on=ads.available&&started&&!!s.journey?.introDone&&(s.extras.played||0)>=AD_HUD_AFTER;$('adHud').hidden=!on;$('privacyBtn').hidden=!ads.privacyRequired;$('privacyBtn').textContent=t('options.privacy');if(!on)return;
 $('adBoostBtn').classList.toggle('active',s.extras.adBoost>0);$('adBoostTime').textContent=s.extras.adBoost>0?clock(s.extras.adBoost):'x2';$('adBoostBtn').setAttribute('aria-label',t('ad.boostTitle'));
 $('chestBtn').hidden=!E.chestReady(s);$('chestBtn').setAttribute('aria-label',t('ad.chestTitle'));}
setInterval(updateAds,1000);
$('startPlaying').onclick=()=>{unlockAudio();music.unlock();askOnce();keepAwake();services.checkUpdate();ads.init().then(()=>{updateAds();updateGoal();$('awayDouble').hidden=!ads.available||awayIdle;$('dailyDouble').hidden=!ads.available;});started=true;if(introAtStart===null)introAtStart=!c.state().journey.introDone;$('welcome').hidden=true;update();const a=c.away?.();if(a)welcomeBack(a.seconds,a.gold,a.sold);};
function relabel(){$('welcome').setAttribute('aria-label',t('welcome.aria'));$('welcomeTag').textContent=t('welcome.tag');$('welcomeTitle').textContent=t('game.title');$('welcomeTitle').hidden=I.lang==='tr';$('welcomeLogo').alt=t('game.title');$('welcomeText').textContent=t('welcome.text');$('startPlaying').textContent=t(c.existing()?'welcome.continue':'welcome.start');$('welcomeNew').textContent=t('welcome.new');
 const other=I.lang==='tr'?'en':'tr';$('welcomeLanguage').textContent=t('language.switch');$('welcomeLanguage').lang=other;$('languageToggle').textContent=t('options.language');
 $('playerBadge').setAttribute('aria-label',t('badge.aria'));$('medalsBtn').setAttribute('aria-label',t('ach.title'));$('sealsBtn').setAttribute('aria-label',t('seal.title'));$('feedbackBtn').textContent=t('options.feedback');$('policyBtn').textContent=t('options.policy');$('closeGoals').setAttribute('aria-label',t('goals.close'));$('goalsTitle').textContent=t('goals.title');paintGold();}
relabel();I.onChange(()=>{relabel();if(highlight&&stage==='dispatch')highlight.textContent=t('action.loadDispatch');if($('goalsDialog').open)openGoals();update();});
// Soft pointer after the tutorial (players got lost there): until level 3, the button the current mission needs glows gently,
// or the mission strip does when the panel showing that button is closed. Nothing is forced; it ends by itself.
const HINT_ACTION={hireWorker:'worker',hireDriver:'caravanWorker',hireMarket:'marketWorker',buildingLevel:'production',caravanLevel:'transport',openTown:'unlock',openRegion:'unlockRegion'};let hinted=null;
function hint(){const s=c.state(),clear=()=>{if(hinted){hinted.classList.remove('hint-target');hinted=null;}};if(!started||!s.journey?.introDone||J.level(s)>3&&J.routeDone(s,E)&&((s.regions.forest.prestige||0)>0||s.extras.empire.resets>0)){clear();return;}
 const m=J.mission(s,E,c.region()),need=m&&!m.ready?needFirst(s,m):null,action=m&&!m.ready?need||HINT_ACTION[m.type]:null;let el=null;
  // "Earn N gold": the town panel's best-value upgrade (★) is the way to get there faster.
    // With no panel open the mission strip glows: its "Show me" opens the town with the best upgrade.
  if(m&&!m.ready&&m.type==='prestigeTarget')el=!$('sheet').hidden&&$('sheet').querySelector('.best')||$('openGoals');
 if(action){const id=m.type==='hireMarket'?m.region:m.town;el=[...$('sheet').querySelectorAll('[data-action="'+action+'"]')].find(b=>!$('sheet').hidden&&(b.dataset.id===id||action==='unlockRegion')&&(action!=='build'&&action!=='worker'||!b.dataset.index||b.dataset.index==='0'))||null;if(!el)el=$('openGoals');}
 if(el!==hinted){clear();if(el){el.classList.add('hint-target');hinted=el;if(el.closest('#sheet'))el.scrollIntoView({block:'nearest',behavior:motion?'smooth':'auto'});}}else if(el&&!el.classList.contains('hint-target'))el.classList.add('hint-target');}// panel refreshes can rewrite a button's classes
function guide(){const s=c.state(),next=J.step(s,E.FIRST);
 // While the first caravan travels, point at the market, where the gold will come from.
 $('nav').querySelector('[data-row=market]')?.classList.toggle('hint-target',next==='travelWait');if(next==='done'){if(!s.journey.introDone){s.journey.introDone=true;c.save();celebrate(['cele.intro'],['cele.introText'],'milestone');services.track('tutorial_complete');askOnce();}stage='done';if(highlight)highlight.classList.remove('guide-target');highlight=null;$('guideStrip').hidden=true;phone.classList.remove('guided');return;}
 if(!started)return;phone.classList.add('guided');$('guideStrip').hidden=false;{const l=s.lines[E.FIRST],left=next==='travelWait'&&l.phase==='outbound'?Math.ceil(l.remaining||0):0;$('guideStrip').textContent=t('guide.'+next)+(left>0?' '+t('guide.secondsLeft',{n:left}):'');}
 const row=['sell','saleWait'].includes(next)?'market':firstRow();if(stage!==next){stage=next;services.track('tutorial_step',{step:next});if(highlight)highlight.classList.remove('guide-target');highlight=null;if(next==='travelWait'){c.travel();lastRow=null;}else if(lastRow!==row||c.selected()!==row){c.showTown(row);lastRow=row;}}
 const action=['build','produce','caravan','dispatch','sell','production'].includes(next)?next:null,target=action?$('sheet').querySelector('[data-action="'+action+'"]'):null;
 if(target&&target!==highlight){if(highlight)highlight.classList.remove('guide-target');highlight=target;target.scrollIntoView({block:'center'});target.focus({preventScroll:true});}if(target){target.classList.add('guide-target');if(next==='dispatch'&&target.textContent!==t('action.loadDispatch'))target.textContent=t('action.loadDispatch');}// the panel is patched in place, so these must be set again after each refresh
}
// The tutorial lets only its highlighted button through, except for the cloud question, which can appear at any step.
function allowedTarget(e){if(!started||c.state().journey.introDone||e.target.closest('#cloudDialog')||e.target.closest('#talkDialog,#storyLine'))return true;const button=e.target.closest('button');return !!button&&button===highlight;}
document.addEventListener('pointerdown',()=>{lastInput=Date.now();},true);
phone.addEventListener('click',e=>{if(!allowedTarget(e)){e.preventDefault();e.stopImmediatePropagation();}},true);
phone.addEventListener('pointerdown',e=>{if(!allowedTarget(e)){e.preventDefault();e.stopImmediatePropagation();}},true);
document.addEventListener('keydown',e=>{if(started&&!c.state().journey.introDone){if(e.key==='Tab'){e.preventDefault();highlight?.focus({preventScroll:true});}else if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();}}},true);
const mmss=sec=>{const r=Math.ceil(sec);return Math.floor(r/60)+':'+String(r%60).padStart(2,'0');};
// Trade Book button: the badge asks for a look when a job can be collected, a rush can start, or the book is brand new.
let jobReady=false,rushKey='';
function bookUpdate(s){const b=$('bookBtn'),x=s.extras.book,show=started&&E.bookOpen(s);b.hidden=!show;if(!show)return;b.setAttribute('aria-label',t('book.title'));const ready=!!x.job&&E.can(s,'bookClaim','x');if(ready&&!jobReady){c.toast(t('book.ready'));tone('goal');}jobReady=ready;b.querySelector('.badge').hidden=!(ready||E.rushReady(s)||!x.jobs&&!x.job);}
// Market Rush bar: stays on screen for the whole run, whatever the player opens. The prize is paid as soon as the third target falls.
function rushChoice(id,run){const d=E.defs[id];return '<button class="rush-pick" data-town="'+id+'"><img src="../assets/art-v3/icons/'+d.material+'.webp" alt=""><b>'+N(d.product)+'</b><small>'+fmt(run.goals[id])+'</small></button>';}
function rushUpdate(s){const r=s.extras.rush,u=r.run,bar=$('rushBar');if(r.lost){r.lost=false;c.toast(t('rush.lost'));services.track('rush_lost',{level:J.level(s),step:r.lostAt?.step??-1,picked:r.lostAt?.picked??-1,...pace()});}// step and picked say where the time ran out: on a target, or on a choice nobody made
 if(u?.won&&!c.readonly()&&started){const time=Math.round(u.time),gold=u.prize||E.rushPrize(s),best=!r.best||u.time<r.best;if(E.act(s,'rushClaim','x')){services.track('rush_win',{level:J.level(s),seconds:time,best:best?1:0});celebrate(['cele.rush'],[best?'cele.rushBest':'cele.rushText',{n:fmt(gold),time:mmss(time)}],'milestone');c.changed();}}
 const run=r.run;bar.hidden=!run||!started;if(!run){rushKey='';return;}const key=run.step+'|'+(run.town||'')+'|'+run.options.join();if(key!==rushKey){rushKey=key;bar.innerHTML='<div class="rush-top"><b>'+t('rush.title')+'</b><span class="rush-step">'+(run.step+1)+'/'+E.RUSH_STEPS+'</span><span class="rush-time"></span></div>'+(run.town?'<div class="rush-now"><img src="../assets/art-v3/icons/'+E.defs[run.town].material+'.webp" alt=""><span class="meter-bar"><i></i></span><small class="rush-count"></small></div>':'<div class="rush-list">'+run.options.map(id=>rushChoice(id,run)).join('')+'</div>');for(const b of bar.querySelectorAll('[data-town]'))b.onclick=()=>{if(!c.readonly()&&E.act(c.state(),'rushPick',b.dataset.town)){tone('goal');buzz(15);c.save();rushUpdate(c.state());}};}
 bar.querySelector('.rush-time').textContent=mmss(run.left);bar.classList.toggle('late',run.left<30);if(run.town){bar.querySelector('.meter-bar i').style.width=Math.min(100,run.done/run.target*100)+'%';bar.querySelector('.rush-count').textContent=fmt(Math.floor(run.done))+' / '+fmt(run.target);}}
function update(){const s=c.state();if(!s.journey)J.init(s,false);$('soundToggle').textContent=t('options.sound',{state:t(s.journey.sound?'sound.on':'sound.off')});$('musicToggle').textContent=t('options.music',{state:t(s.journey.music!==false?'sound.on':'sound.off')});$('vibrationToggle').textContent=t('options.vibration',{state:t(s.journey.vibration!==false?'sound.on':'sound.off')});$('animToggle').textContent=t('options.animations',{state:t(s.journey.animations!==false?'sound.on':'sound.off')});document.body.classList.toggle('no-ambient',s.journey.animations===false);$('cloudBtn').hidden=!services.native;$('cloudBtn').textContent=t('options.cloud',{state:t(cloudOn?'cloud.connected':'cloud.connect')});$('awakeToggle').textContent=t('options.keepAwake',{state:t(s.journey.keepAwake!==false?'sound.on':'sound.off')});const l=J.level(s);$('playerBadge').textContent=String(l);$('playerBadge').title=t('badge.title',{level:l,next:fmt(J.next(s))});
 if(started&&l>s.journey.seenLevel){s.journey.seenLevel=l;c.save();const feature=l>=J.PRESTIGE_LEVEL&&levelBefore<J.PRESTIGE_LEVEL?'level.prestige':l>=4&&levelBefore<4?'level.third':l>=3&&levelBefore<3?'level.second':l>=2&&levelBefore<2?'level.workers':'';celebrate(['cele.level',{n:l}],feature?[feature]:[''],'level');services.track('level_up',{level:l});levelBefore=l;}
 if(!c.readonly()&&started){const diff=Math.max(0,s.earned-lastEarning);pendingGold+=diff;for(const id of E.IDS){const n=s.lines[id].sold-lastSold[id];if(n>0)pendingSold[id]=(pendingSold[id]||0)+n;}const now=Date.now();if(pendingGold>=1&&now-lastSale>1100){const ids=Object.keys(pendingSold).sort((a,b)=>pendingSold[b]-pendingSold[a]),units=ids.reduce((n,id)=>n+pendingSold[id],0);$('saleFeedback').innerHTML=(ids.length?ids.slice(0,3).map(id=>'<img class="ico" src="../assets/art-v3/icons/'+E.defs[id].material+'.webp" alt="">').join('')+fmt(Math.round(units))+' → ':'')+'+'+fmt(pendingGold)+'<img class="ico" src="../assets/nano-art/gold.webp" alt="">';$('saleFeedback').classList.remove('show');void $('saleFeedback').offsetWidth;$('saleFeedback').classList.add('show');
  // Real sales only: a few coins from the market to the gold counter, at a calm pace and only while the player is playing.
  if(now-lastSaleCoins>4000&&now-lastInput<30000){const here=ids.length&&c.onMap()&&E.defs[ids[0]].region===c.region(),m=here?document.querySelector('#scene [data-market] circle')?.getBoundingClientRect():null,box=phone.getBoundingClientRect(),seen=m&&m.top+m.height/2>box.top&&m.top+m.height/2<box.bottom&&m.left+m.width/2>box.left&&m.left+m.width/2<box.right;flyCoins(seen?m:$('saleFeedback').getBoundingClientRect(),4);lastSaleCoins=now;}
  pendingGold=0;pendingSold={};lastSale=now;
  // The sale sound stays in the background: at most every 5 s, and only while the player is actually playing.
  if(now-lastSaleSound>5000&&now-lastInput<30000){tone('sale');lastSaleSound=now;}}}
 lastEarning=s.earned;for(const id of E.IDS)lastSold[id]=s.lines[id].sold;
 // Earning milestones, with quiet numbers that do not land on a level-up.
 if(started&&s.journey.introDone){const j=s.journey,MARKS=[1000,10000,1e6,1e9];if(j.goldMark===undefined)j.goldMark=MARKS.filter(n=>s.earned>=n).length;else if(j.goldMark<MARKS.length&&s.earned>=MARKS[j.goldMark]){const n=MARKS[j.goldMark];j.goldMark++;c.save();celebrate(['cele.gold',{n:fmt(n)}],['cele.goldText'],'goal');}}
 guide();if(stage==='done')updateGoal();pump();storyTick(s);bookTip(s);tokenTick(s);
 const sb=$('sealsBtn'),showSeals=started&&(E.empireReady(s)||s.extras.empire.resets>0);sb.hidden=!showSeals;if(showSeals){const n=Object.keys(E.SEAL_TREE).filter(id=>E.can(s,'seal',id)).length,b=sb.querySelector('.badge');if(b.textContent!==String(n))b.textContent=String(n);b.hidden=!n;}const mb=$('medalsBtn'),showMedals=started&&s.journey.introDone;mb.hidden=!showMedals;if(showMedals){const n=E.achievements(s).filter(a=>a.ready).length,b=mb.querySelector('.badge');if(b.textContent!==String(n))b.textContent=String(n);b.hidden=!n;}
 bookUpdate(s);rushUpdate(s);music.update();if(cloudOffer&&started&&!cloudOffer.shown&&!document.querySelector('dialog[open]')){cloudOffer.shown=true;showCloudOffer();}checkMedals();maybeDaily();merchantTick();}
function reset(){started=true;if(introAtStart===null)introAtStart=!c.state().journey.introDone;$('welcome').hidden=true;stage='';lastRow=null;lastEarning=c.state().earned;pendingGold=0;pendingSold={};queue=[];levelBefore=1;update();}
return {gapText,update,reset,gold,action,welcomeBack,track,cloudState,offerCloud,help,firstHelp};
